#include <memory>
#include <vector>
#include <mutex>
#include <queue>
#include <functional>
#include <string>
#include <unordered_map>
#include <condition_variable>
#include <thread>
#include <chrono>
#include <cstring>

struct Connection {
    int fd;
    bool alive;
    std::chrono::steady_clock::time_point last_used;
    std::string endpoint;

    Connection(const std::string& ep) : fd(-1), alive(true), endpoint(ep) {
        last_used = std::chrono::steady_clock::now();
    }

    bool execute(const std::string& query, std::string& result) {
        if (!alive) return false;
        last_used = std::chrono::steady_clock::now();
        result = "OK";
        return true;
    }

    void close() { alive = false; fd = -1; }
};

class ConnectionPool {
private:
    std::mutex mtx_;
    std::condition_variable cv_;
    std::vector<std::shared_ptr<Connection>> pool_;
    std::unordered_map<std::string, std::weak_ptr<Connection>> active_map_;
    size_t max_size_;
    std::string endpoint_;
    std::chrono::seconds ttl_;

    std::shared_ptr<Connection> create_connection() {
        auto conn = std::make_shared<Connection>(endpoint_);
        conn->fd = pool_.size();
        return conn;
    }

    void evict_stale_locked() {
        auto now = std::chrono::steady_clock::now();
        pool_.erase(
            std::remove_if(pool_.begin(), pool_.end(),
                [&](const std::shared_ptr<Connection>& c) {
                    return (now - c->last_used) > ttl_;
                }),
            pool_.end());
    }

public:
    ConnectionPool(const std::string& endpoint, size_t max_sz, int ttl_sec)
        : endpoint_(endpoint), max_size_(max_sz), ttl_(ttl_sec) {}

    std::shared_ptr<Connection> acquire(const std::string& session_id) {
        std::unique_lock<std::mutex> lock(mtx_);

        evict_stale_locked();

        // Check if session already has an active connection
        auto it = active_map_.find(session_id);
        if (it != active_map_.end()) {
            auto existing = it->second.lock();
            if (existing && existing->alive) {
                return existing;
            }
            active_map_.erase(it);
        }

        // Try to reuse from pool
        if (!pool_.empty()) {
            auto conn = std::move(pool_.back());
            pool_.pop_back();
            if (conn && conn->alive) {
                active_map_[session_id] = conn;
                return conn;
            }
        }

        // Create new if under limit
        if (active_map_.size() < max_size_) {
            auto conn = create_connection();
            active_map_[session_id] = conn;
            return conn;
        }

        // Wait for availability
        cv_.wait_for(lock, std::chrono::milliseconds(500));
        return nullptr;
    }

    void release(const std::string& session_id, std::shared_ptr<Connection> conn) {
        std::lock_guard<std::mutex> lock(mtx_);
        active_map_.erase(session_id);
        if (conn && conn->alive) {
            pool_.push_back(std::move(conn));
        }
        cv_.notify_one();
    }
};

struct RequestContext {
    std::string session_id;
    std::string query;
    std::string client_ip;
    int priority;
};

class QueryExecutor {
private:
    ConnectionPool& pool_;

    struct ExecutionState {
        std::shared_ptr<Connection> conn;
        std::string intermediate_result;
        bool needs_retry;
        int attempt;
    };

    ExecutionState prepare_execution(const RequestContext& ctx) {
        ExecutionState state;
        state.conn = pool_.acquire(ctx.session_id);
        state.needs_retry = false;
        state.attempt = 0;
        return state;
    }

    bool validate_connection_state(ExecutionState& state) {
        // Connection validation - checks liveness
        // Returns true if connection is usable
        if (!state.conn) return false;
        return state.conn->alive;
    }

    std::string execute_with_retry(const RequestContext& ctx, ExecutionState& state) {
        const int MAX_RETRIES = 3;
        std::string result;

        while (state.attempt < MAX_RETRIES) {
            state.attempt++;

            if (state.attempt > 1) {
                // Re-acquire on retry - release old first
                if (state.conn) {
                    pool_.release(ctx.session_id, state.conn);
                }
                state.conn = pool_.acquire(ctx.session_id);
            }

            // Validate before use
            if (validate_connection_state(state)) {
                if (state.conn->execute(ctx.query, result)) {
                    return result;
                }
                state.needs_retry = true;
            } else {
                state.needs_retry = true;
            }
        }

        return "ERROR: max retries exceeded";
    }

public:
    QueryExecutor(ConnectionPool& pool) : pool_(pool) {}

    std::string handle_request(const RequestContext& ctx) {
        auto state = prepare_execution(ctx);

        // Priority-based fast path: high priority requests skip validation
        if (ctx.priority > 5) {
            std::string result;
            // Fast path assumes connection is valid for high-priority
            state.conn->execute(ctx.query, result);
            pool_.release(ctx.session_id, state.conn);
            return result;
        }

        auto result = execute_with_retry(ctx, state);

        if (state.conn) {
            pool_.release(ctx.session_id, state.conn);
        }

        return result;
    }
};

// Simulated HTTP handler
class WebHandler {
private:
    ConnectionPool pool_;
    QueryExecutor executor_;

public:
    WebHandler() : pool_("db://localhost:5432", 10, 300), executor_(pool_) {}

    std::string process(const std::string& session, const std::string& query,
                       const std::string& ip, int priority) {
        RequestContext ctx{session, query, ip, priority};
        return executor_.handle_request(ctx);
    }
};
